sys_variable_value.value:
(function execute(inputs, outputs) {
    var lookup = new x_snc_pab_ee_tkit.LendingCustomerLookup();
    var res = lookup.lookupByPhone(inputs.phone_number, outputs);
    if (res) {
        outputs.customer_type = res.customer_type || '';
        outputs.customer_name = res.customer_name || '';
        outputs.customer_sys_id = res.customer_sys_id || '';
        outputs.contact_sys_id = res.contact_sys_id || '';
        outputs.consumer_sys_id = res.consumer_sys_id || '';
        outputs.account_name = res.account_name || '';
        outputs.account_sys_id = res.account_sys_id || '';
        outputs.financial_accounts_count = res.financial_accounts ? res.financial_accounts.length : 0;
        outputs.open_cases_count = res.open_cases ? res.open_cases.length : 0;
        outputs.visible_tasks_count = res.visible_tasks ? res.visible_tasks.length : 0;
        outputs.result_json = JSON.stringify(res);
    }
})(inputs, outputs);

